-- Dort asama kule + pilot pratik. Eski dinle/konus/senaryo arsivlenir.
UPDATE learning_steps SET status = 'ARCHIVED'
 WHERE path_id IN (SELECT id FROM learning_paths WHERE slug IN ('kule-ol', 'pilot-ol'))
   AND step_type IN ('LISTEN', 'SPEAK', 'SCENARIO', 'LIVE_PRACTICE', 'PRACTICE')
   AND status = 'PUBLISHED';

UPDATE learning_steps SET configuration = coalesce(configuration, '{}'::jsonb) || '{"stage":1}'::jsonb
 WHERE slug IN ('kule-kimdir', 'turkiyede-atc', 'ivao-rating', 'twr-alfabe',
                'dinle-ilk-cagri-pilot', 'plt-alfabe') AND status = 'PUBLISHED';

UPDATE learning_paths SET description = 'Dort asama: zemin, trafik, PAN, MAYDAY. Yaklasik 100 pratik. Giris yapan puan biriktirir.'
 WHERE slug = 'kule-ol';
UPDATE learning_paths SET description = 'Dort asama: yer, patern, PAN, MAYDAY. Read-back ve acil cagri. Giris yapan puan biriktirir.'
 WHERE slug = 'pilot-ol';

